def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    recent_window = min(10, n)
    recent_opp_d = sum(1 for a, b in history[-recent_window:] if b == 'D')

    if recent_opp_d >= 4:
        return 'D'

    if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'

    retal = 0
    forgive = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'D':
                retal += 1
            else:
                forgive += 1
    my_d_count = retal + forgive

    mode = 'unknown'
    if my_d_count >= 1:
        ret_rate = retal / my_d_count
        if ret_rate <= 0.25:
            mode = 'exploit'
        elif ret_rate >= 0.5:
            mode = 'defensive'

    if n >= 98 and mode == 'exploit':
        return 'D'

    if mode == 'defensive':
        return 'C'

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if last_my == 'C':
            return 'D'
        return 'C'

    if mode == 'exploit':
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    opp_d_total = sum(1 for a, b in history if b == 'D')
    if opp_d_total == 0 and n >= 9 and (n + 1) % 10 == 0:
        return 'D'

    return 'C'
